```java
// Good: Proper validation and use of URL to prevent SSRF attacks
public class GoodExample {
    public static void main(String[] args) {
        try {
            // Validate the URL before using it
            String userInput = "http://internal-service:8080/admin";
            if (isValidUrl(userInput)) {
                java.net.URL url = new java.net.URL(userInput);
                java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
                connection.setRequestMethod("GET");
                int responseCode = connection.getResponseCode();
                System.out.println("Response Code: " + responseCode);
            } else {
                System.out.println("Invalid URL, access denied.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method to validate the URL
    private static boolean isValidUrl(String urlStr) {
        try {
            java.net.URL url = new java.net.URL(urlStr);
            // Check if the URL is allowed (e.g., only allow external domains)
            String host = url.getHost();
            // Example: Only allow URLs from example.com
            return host != null && host.contains("example.com");
        } catch (java.net.MalformedURLException e) {
            return false;
        }
    }
}
